class Solution {
public:
    int findRadius(vector<int>& houses, vector<int>& heaters) {
        sort(heaters.begin(), heaters.end());
        int ans = 0;
        for (int h : houses) {
            auto it = lower_bound(heaters.begin(), heaters.end(), h);
            int dist = INT_MAX;
            if (it != heaters.end()) dist = *it - h;
            if (it != heaters.begin()) dist = min(dist, h - *prev(it));
            ans = max(ans, dist);
        }
        return ans;
    }
};
